do $$ begin create role anon; exception when others then null; end $$; do $$ begin create role authenticated; exception when others then null; end $$; do $$ begin create role service_role; exception when others then null; end $$;
create schema dm_private; create schema dm_ad_rewards;
create table public.students(id uuid primary key default gen_random_uuid(), username text, status text default 'approved', role text default 'student', frozen_at timestamptz, profile jsonb default '{}', class_no int, selected_class int, gold numeric default 0, energy int default 10, energy_max int default 25);
create table public.extra_data(student_id uuid, key_name text, value jsonb, updated_at timestamptz, primary key(student_id,key_name));
create table public.word_bank(id uuid primary key default gen_random_uuid(), class_no int, unit_no int, english text, turkish text, active boolean default true);
create table public.dm_game_reward_runs(student_id uuid, run_id text, game_key text, class_no int, units int[], xp int, gold int, created_at timestamptz default now(), topic_key text, primary key(student_id,run_id));
create table public.student_blocks(blocker_id uuid, blocked_id uuid);
create table dm_ad_rewards.intents(id uuid primary key default gen_random_uuid(), student_id uuid, kind text, request_key uuid, created_at timestamptz default now(), expires_at timestamptz default now()+interval '10 minutes', claimed_at timestamptz, canceled_at timestamptz, transaction_id text, added int, reward_day date default (now() at time zone 'Europe/Istanbul')::date);
create table dm_ad_rewards.premium_offers(id uuid primary key default gen_random_uuid(), student_id uuid references public.students(id) on delete cascade, game text, created_at timestamptz default now(), expires_at timestamptz default now()+interval '15 minutes', ad_id uuid unique references dm_ad_rewards.intents(id), reward_day date, redeemed_at timestamptz, constraint premium_offers_game_check check (game = any (array['word-match','papizzle'])));
create function public.dm_plan(actor uuid, account_role text default 'student') returns text language sql as $$ select coalesce((select profile->>'plan' from public.students where id=actor),'free') $$;
create function public.dm_student_level(xp numeric) returns int language sql as $$ select 1+floor(xp/1000)::int $$;
create function public.dm_social_allowed(p uuid, f text default 'social') returns boolean language sql as $$ select coalesce((select (profile->>'noduel') is null from public.students where id=p),true) $$;
create function public.dm_blocked(a uuid,b uuid) returns boolean language sql as $$ select exists(select 1 from public.student_blocks where (blocker_id=a and blocked_id=b) or (blocker_id=b and blocked_id=a)) $$;
create function dm_private.rpc_ogrenci(p_t text, p_ogrenci text) returns public.students language sql as $$ select * from public.students where id::text=p_t $$;
insert into public.word_bank(class_no,unit_no,english,turkish)
